package client

// Recording processing documents use the same account API for every surface.
// Original versions are evidence; metadata corrections never trigger a provider call.
func init() {
	RecordingDocuments["ResumeRecordingLearning"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!) { ResumeRecordingLearning(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration) { sourceGeneration hasAgent hasStoppedReading pendingDocumentCount digestedDocumentCount lastPublishedSourceGeneration isCurationPending knowledgeSource { id kind name specification { settings } enabled cron lastRunAt nextRunAt lastError documentCount chunkCount } } }`
	RecordingDocuments["ReadRecordingTranscriptPassageOffset"] = `query ($recordingTranscriptRunId: String!, $passageStartMS: Int64!, $passageEndMS: Int64!) { ReadRecordingTranscriptPassageOffset(recordingTranscriptRunId: $recordingTranscriptRunId, passageStartMS: $passageStartMS, passageEndMS: $passageEndMS) }`
	RecordingDocuments["SaveRecordingSourceSchedule"] = `mutation ($sourceId: String!, $cron: String!) { SaveRecordingSourceSchedule: SaveAgentKnowledgeSource(sourceId: $sourceId, cron: $cron) { id kind name enabled cron nextRunAt } }`
	RecordingDocuments["ReadRecordingTranscriptionAvailability"] = `query { ReadRecordingTranscriptionAvailability: ReadRecordingLimits { maximumMediaBytes maximumAccountBytes uploadPartBytes isTranscriptionAvailable transcriptionUnavailableMessage transcriptionProviderModelName } }`
	RecordingDocuments["ListAgentModels"] = `query { ListAgentModels { name contextLength canTranscribe hasSpeakerDiarization hasSegmentTimestamps hasSpeakerReferences maximumAudioBytes maximumSpeakerReferenceCount } }`
	RecordingDocuments["ReadRecordingTranscript"] = `query ($recordingTranscriptRunId: String!, $segmentOffset: Int!, $pageSize: Int!) { ReadRecordingTranscript(recordingTranscriptRunId: $recordingTranscriptRunId, segmentOffset: $segmentOffset, pageSize: $pageSize) { transcriptRun { id recordingId recordingMediaId createdAt updatedAt clientRunId versionNumber recordingProcessingState providerModelName originalSha256 derivedDurationMS processingErrorMessage isReprocessingRequested completedAt } segments { id recordingTranscriptRunId recordingTranscriptionAttemptId localSpeakerId segmentStartMS segmentEndMS transcriptText effectiveTranscriptText appliedTextCorrectionId hasUnalignedTextCorrection effectiveSpeakerIdentityId effectiveSpeakerName hasUserConfirmedSpeaker isAccountOwner hasUnalignedSpeakerCorrection appliedSpeakerCorrectionId } attempts { id recordingTranscriptRunId recordingAudioChunkId attemptIndex createdAt submittedAt completedAt recordingAttemptState providerModelName attemptErrorMessage inputAudioTokens inputTextTokens promptTokens completionTokens providerAudioDurationMS hasProviderUsage estimatedCostAmount actualCostAmount currencyCode referenceBlobIds } segmentCount hasMoreSegments } }`
	RecordingDocuments["RequestRecordingTranscription"] = `mutation ($recordingMediaId: String!, $clientRunId: String!, $isReprocessingRequested: Boolean!) { RequestRecordingTranscription(recordingMediaId: $recordingMediaId, clientRunId: $clientRunId, isReprocessingRequested: $isReprocessingRequested) { id recordingId recordingMediaId createdAt updatedAt clientRunId versionNumber recordingProcessingState providerModelName originalSha256 derivedDurationMS processingErrorMessage isReprocessingRequested completedAt } }`
	RecordingDocuments["CancelRecordingTranscription"] = `mutation ($recordingTranscriptRunId: String!) { CancelRecordingTranscription(recordingTranscriptRunId: $recordingTranscriptRunId) { id recordingId recordingMediaId createdAt updatedAt clientRunId versionNumber recordingProcessingState providerModelName originalSha256 derivedDurationMS processingErrorMessage isReprocessingRequested completedAt } }`
	RecordingDocuments["RetryRecordingTranscription"] = `mutation ($recordingTranscriptRunId: String!) { RetryRecordingTranscription(recordingTranscriptRunId: $recordingTranscriptRunId) { id recordingId recordingMediaId createdAt updatedAt clientRunId versionNumber recordingProcessingState providerModelName originalSha256 derivedDurationMS processingErrorMessage isReprocessingRequested completedAt } }`
	RecordingDocuments["SuggestRecordingSpeakerNames"] = `query ($searchText: String, $pageSize: Int) { SuggestRecordingSpeakerNames(searchText: $searchText, pageSize: $pageSize) { confirmedName speakerNameSource } }`
	RecordingDocuments["ReadRecordingSpeakers"] = `query ($recordingId: String!) { ReadRecordingSpeakers(recordingId: $recordingId) { sourceGeneration speakerIdentities { id confirmedName isAccountOwner createdAt } speakerCorrections { id recordingId recordingMediaId recordingTranscriptionAttemptId speakerIdentityId clientCorrectionId localSpeakerId passageStartMS passageEndMS sourceGeneration createdAt isRemoved } voiceReferences { id recordingId recordingMediaId recordingTranscriptRunId recordingSpeakerCorrectionId speakerIdentityId recordingBlobId passageStartMS passageEndMS sourceGeneration isRevoked createdAt } } }`
	RecordingDocuments["ReadRecordingLearning"] = `query ($recordingId: String!) { ReadRecordingLearning(recordingId: $recordingId) { sourceGeneration hasAgent hasStoppedReading pendingDocumentCount digestedDocumentCount lastPublishedSourceGeneration isCurationPending knowledgeSource { id kind name specification { settings } enabled cron lastRunAt nextRunAt lastError documentCount chunkCount } } }`
	RecordingDocuments["ReadRecordingReferenceInvalidations"] = `query ($recordingId: String!) { ReadRecordingReferenceInvalidations(recordingId: $recordingId) { id recordingId recordingTranscriptRunId recordingTranscriptionAttemptId referenceBlobId referenceRecordingId referenceTranscriptRunId speakerIdentityId invalidatedConfirmedName referencePassageStartMS referencePassageEndMS referenceSourceGeneration invalidationMessage createdAt isReconciled } }`
	RecordingDocuments["NameRecordingTemporarySpeaker"] = `mutation ($recordingId: String!, $speakerLabel: String!, $confirmedName: String!, $isAccountOwner: Boolean) { NameRecordingTemporarySpeaker(recordingId: $recordingId, speakerLabel: $speakerLabel, confirmedName: $confirmedName, isAccountOwner: $isAccountOwner) }`
	RecordingDocuments["SeparateRecordingTemporarySpeaker"] = `mutation ($recordingId: String!, $speakerLabel: String!) { SeparateRecordingTemporarySpeaker(recordingId: $recordingId, speakerLabel: $speakerLabel) }`
	RecordingDocuments["CorrectRecordingSpeaker"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!, $clientCorrectionId: String!, $confirmedName: String!, $isAccountOwner: Boolean, $recordingTranscriptionAttemptId: String!, $localSpeakerId: String!, $passageStartMS: Int64!, $passageEndMS: Int64!) { CorrectRecordingSpeaker(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration, clientCorrectionId: $clientCorrectionId, confirmedName: $confirmedName, isAccountOwner: $isAccountOwner, recordingTranscriptionAttemptId: $recordingTranscriptionAttemptId, localSpeakerId: $localSpeakerId, passageStartMS: $passageStartMS, passageEndMS: $passageEndMS) { sourceGeneration speakerIdentities { id confirmedName isAccountOwner createdAt } speakerCorrections { id recordingId recordingMediaId recordingTranscriptionAttemptId speakerIdentityId clientCorrectionId localSpeakerId passageStartMS passageEndMS sourceGeneration createdAt isRemoved } voiceReferences { id recordingId recordingMediaId recordingTranscriptRunId recordingSpeakerCorrectionId speakerIdentityId recordingBlobId passageStartMS passageEndMS sourceGeneration isRevoked createdAt } } }`
	RecordingDocuments["RenameRecordingSpeaker"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!, $speakerIdentityId: String!, $confirmedName: String!) { RenameRecordingSpeaker(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration, speakerIdentityId: $speakerIdentityId, confirmedName: $confirmedName) { sourceGeneration speakerIdentities { id confirmedName isAccountOwner createdAt } speakerCorrections { id recordingId recordingMediaId recordingTranscriptionAttemptId speakerIdentityId clientCorrectionId localSpeakerId passageStartMS passageEndMS sourceGeneration createdAt isRemoved } voiceReferences { id recordingId recordingMediaId recordingTranscriptRunId recordingSpeakerCorrectionId speakerIdentityId recordingBlobId passageStartMS passageEndMS sourceGeneration isRevoked createdAt } } }`
	RecordingDocuments["RemoveRecordingSpeakerCorrection"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!, $recordingSpeakerCorrectionId: String!) { RemoveRecordingSpeakerCorrection(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration, recordingSpeakerCorrectionId: $recordingSpeakerCorrectionId) { sourceGeneration speakerIdentities { id confirmedName isAccountOwner createdAt } speakerCorrections { id recordingId recordingMediaId recordingTranscriptionAttemptId speakerIdentityId clientCorrectionId localSpeakerId passageStartMS passageEndMS sourceGeneration createdAt isRemoved } voiceReferences { id recordingId recordingMediaId recordingTranscriptRunId recordingSpeakerCorrectionId speakerIdentityId recordingBlobId passageStartMS passageEndMS sourceGeneration isRevoked createdAt } } }`
	RecordingDocuments["UndoRecordingSpeakerNaming"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!, $recordingSpeakerCorrectionId: String!) { UndoRecordingSpeakerNaming(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration, recordingSpeakerCorrectionId: $recordingSpeakerCorrectionId) { sourceGeneration speakerIdentities { id confirmedName isAccountOwner createdAt } speakerCorrections { id recordingId recordingMediaId recordingTranscriptionAttemptId speakerIdentityId clientCorrectionId localSpeakerId passageStartMS passageEndMS sourceGeneration createdAt isRemoved } voiceReferences { id recordingId recordingMediaId recordingTranscriptRunId recordingSpeakerCorrectionId speakerIdentityId recordingBlobId passageStartMS passageEndMS sourceGeneration isRevoked createdAt } } }`
	RecordingDocuments["DeleteRecordingVoiceReference"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!, $recordingVoiceReferenceId: String!) { DeleteRecordingVoiceReference(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration, recordingVoiceReferenceId: $recordingVoiceReferenceId) { sourceGeneration speakerIdentities { id confirmedName isAccountOwner createdAt } speakerCorrections { id recordingId recordingMediaId recordingTranscriptionAttemptId speakerIdentityId clientCorrectionId localSpeakerId passageStartMS passageEndMS sourceGeneration createdAt isRemoved } voiceReferences { id recordingId recordingMediaId recordingTranscriptRunId recordingSpeakerCorrectionId speakerIdentityId recordingBlobId passageStartMS passageEndMS sourceGeneration isRevoked createdAt } } }`
	RecordingDocuments["ReadRecordingTranscriptTextCorrections"] = `query ($recordingId: String!) { ReadRecordingTranscriptTextCorrections(recordingId: $recordingId) { id recordingId recordingMediaId recordingTranscriptRunId recordingTranscriptSegmentId clientCorrectionId passageStartMS passageEndMS originalTranscriptText correctedTranscriptText sourceGeneration createdAt isRemoved textCorrectionOrigin glossaryTerm originalPhrase correctedPhrase } }`
	RecordingDocuments["CorrectRecordingTranscriptText"] = `mutation ($recordingId: String!, $recordingTranscriptSegmentId: String!, $expectedSourceGeneration: Int64!, $clientCorrectionId: String!, $correctedTranscriptText: String!) { CorrectRecordingTranscriptText(recordingId: $recordingId, recordingTranscriptSegmentId: $recordingTranscriptSegmentId, expectedSourceGeneration: $expectedSourceGeneration, clientCorrectionId: $clientCorrectionId, correctedTranscriptText: $correctedTranscriptText) { id recordingId recordingMediaId recordingTranscriptRunId recordingTranscriptSegmentId clientCorrectionId passageStartMS passageEndMS originalTranscriptText correctedTranscriptText sourceGeneration createdAt isRemoved textCorrectionOrigin glossaryTerm originalPhrase correctedPhrase } }`
	RecordingDocuments["RemoveRecordingTranscriptTextCorrection"] = `mutation ($recordingId: String!, $recordingTranscriptTextCorrectionId: String!, $expectedSourceGeneration: Int64!) { RemoveRecordingTranscriptTextCorrection(recordingId: $recordingId, recordingTranscriptTextCorrectionId: $recordingTranscriptTextCorrectionId, expectedSourceGeneration: $expectedSourceGeneration) }`
	RecordingDocuments["UpdateRecordingMetadata"] = `mutation ($recordingId: String!, $expectedSourceGeneration: Int64!, $recordingTitle: String, $recordedAt: DateTime) { UpdateRecordingMetadata(recordingId: $recordingId, expectedSourceGeneration: $expectedSourceGeneration, recordingTitle: $recordingTitle, recordedAt: $recordedAt) { id userId clientRecordingId recordingTitle recordingTitleSource recordingSummary recordingOrigin recordingCaptureState sourceGeneration timelineDurationMS recordedAt } }`
	RecordingDocuments["ImportRecordingAttachment"] = `mutation ($agentAttachmentId: String!, $clientRecordingId: String!, $recordingTitle: String!, $recordingMediaId: String) { ImportRecordingAttachment(agentAttachmentId: $agentAttachmentId, clientRecordingId: $clientRecordingId, recordingTitle: $recordingTitle, recordingMediaId: $recordingMediaId) { recording { id userId clientRecordingId recordingTitle recordingTitleSource recordingSummary recordingOrigin recordingCaptureState sourceGeneration timelineDurationMS } mediaFiles { id recordingId clientMediaId originalFilename originalContentType originalSizeBytes originalSha256 timelineStartMS mediaDurationMS partCount recordingUploadState verifiedAt } uploadParts { recordingMediaId partIndex partSizeBytes partSha256 storedAt } } }`
	RecordingDocuments["ReadRecordingProcessing"] = `query ($recordingId: String!) { ReadRecordingProcessing: ReadRecording(recordingId: $recordingId) { recording { id userId clientRecordingId recordingTitle recordingTitleSource recordingSummary recordingOrigin recordingCaptureState sourceGeneration timelineDurationMS recordedAt } transcriptRuns { id recordingId recordingMediaId createdAt updatedAt clientRunId versionNumber recordingProcessingState providerModelName originalSha256 derivedDurationMS processingErrorMessage isReprocessingRequested completedAt } } }`
	RecordingDocuments["ReadRecordingTranscriptTimeline"] = `query ($recordingId: String!, $segmentOffset: Int!, $pageSize: Int!, $isUnnamedOnly: Boolean) { ReadRecordingTranscriptTimeline(recordingId: $recordingId, segmentOffset: $segmentOffset, pageSize: $pageSize, isUnnamedOnly: $isUnnamedOnly) { sourceGeneration segments { id recordingTranscriptRunId recordingTranscriptionAttemptId localSpeakerId segmentStartMS segmentEndMS transcriptText effectiveTranscriptText appliedTextCorrectionId hasUnalignedTextCorrection effectiveSpeakerIdentityId effectiveSpeakerName hasUserConfirmedSpeaker isRecognizedSpeaker isAccountOwner hasUnalignedSpeakerCorrection appliedSpeakerCorrectionId temporarySpeakerLabel mergedTemporarySpeakerLabel isFiller } transcriptRuns { id recordingId recordingMediaId createdAt updatedAt clientRunId versionNumber recordingProcessingState providerModelName originalSha256 derivedDurationMS processingErrorMessage isReprocessingRequested completedAt handoffStartMS } temporarySpeakers { speakerLabel speakerIdentityId mergedIntoSpeakerLabel } segmentCount hasMoreSegments liveUtterances { id utteranceId utteranceStartMS utteranceEndMS transcriptText } } }`
}
